arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: <TOKEN>' -d '{"query":"{ __schema { mutationType { fields { name args { name type { name kind ofType { name kind } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    for a in f.get('args',[]):
        t=a['type']
        tn=t.get('name') or (t.get('ofType') or {}).get('name')
        if tn in ('TeamUpdateInput','TeamInput') or 'Team' in str(tn) and 'Update' in str(tn):
            print(f['name'], '->', a['name'], tn)
"

